import path from 'node:path';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import type { DbHandle } from './index.js';

/**
 * Apply every committed migration in ./drizzle (project root).
 * Migrations are plain SQL generated by `npm run db:generate`; this runner is
 * used by `npm run db:migrate` and by the test suite, which runs against an
 * ephemeral Postgres (CI service container or local `docker compose up -d db`).
 */
export async function runMigrations(handle: DbHandle): Promise<void> {
  await migrate(handle.db, { migrationsFolder: path.join(process.cwd(), 'drizzle') });
}
